import {hero,teamLinks} from './engine.mjs';
import {ZONES,ROLES,adjacent,zoneOf} from './strategy.mjs';
export function strategyMarkup(game,side,plan,selected,{esc,waiting=false,connected=true,rematch=false,online=game.mode==='online'}={}){
 const player=game.players[side],chosen=plan.find(p=>p.id===selected)||plan[0],h=hero(chosen?.id);
 const bonds=teamLinks(player.team);
 return `<div class="strategy-inner"><div class="strategy-heading"><div><span class="eyebrow">GİZLİ SAVAŞ PLANI · ${esc(player.name)}</span><h2>Zaferi <em>yerleştir.</em></h2><p>${waiting?'Planın kilitlendi. Rakibin onaylayınca dizilişler aynı anda açılacak.':'Bir kahraman seç, sonra yerleştireceğin konuma dokun. Dolu konumlar yer değiştirir.'}</p></div><span class="strategy-seal">${waiting?'✓ KİLİTLENDİ':'◇ SADECE SEN GÖRÜRSÜN'}</span></div>
 <div class="strategy-layout"><section class="formation-board" aria-label="Takım dizilişi"><div class="formation-enemy">↑ RAKİP TAKIM / SALDIRI YÖNÜ ↑</div><div class="zone-heads">${ZONES.map(z=>`<div><b>${z.symbol} ${z.name}</b><span>${z.id==='cover'?'Güvenli atış':z.id==='open'?'Risk ve güç':'Menzil avantajı'}</span></div>`).join('')}</div>${[0,1].map(row=>`<div class="formation-row-label">${row===0?'01 / ÖN SAF · YAKIN DÖVÜŞÜ KARŞILAR':'02 / ARKA SAF · ÖN SAFIN KORUMASINDA'}</div><div class="formation-row">${[0,1,2].map(col=>{const slot=row*3+col,p=plan.find(p=>p.slot===slot),hh=hero(p?.id);return `<button class="formation-slot zone-${ZONES[col].id} ${p?.id===selected?'selected':''} ${p?'occupied':''}" data-action="strategy-slot" data-id="${slot}" ${waiting?'disabled':''} aria-label="${row===0?'Ön saf':'Arka saf'} ${ZONES[col].name}${hh?' · '+hh.name:''}" aria-pressed="${p?.id===selected}"><span class="slot-number">${String(slot+1).padStart(2,'0')}</span>${hh?`<img src="/assets/${hh.id}.jpg" alt=""><div class="slot-hero"><b>${hh.name}</b><span>${ROLES.find(r=>r.id===p.role).short}${hh.flight?' · UÇUŞ':''}</span></div>`:'<span class="slot-empty">＋<small>YERLEŞTİR</small></span>'}</button>`;}).join('')}</div>`).join('')}<div class="formation-legend"><span>◇ Komşular birbirini korur</span><span>✦ Yakın ikililer daha hızlı dolar</span></div></section>
 <aside class="strategy-inspector"><span class="eyebrow">KAHRAMANLARIN</span><div class="strategy-roster">${player.team.map(id=>`<button data-action="strategy-hero" data-id="${id}" class="${selected===id?'selected':''}" aria-label="${hero(id).name} seç" ${waiting?'disabled':''}><img src="/assets/${id}.jpg" alt=""></button>`).join('')}</div>${h?`<h3>${h.name}</h3><p class="strategy-traits">${h.combat==='ranged'?'MENZİLLİ':'YAKIN DÖVÜŞ'} · HIZ ${h.stats[2]}${h.flight?' · UÇABİLİR':''}</p><label class="strategy-role-label" for="strategy-role">Savaş görevi</label><select id="strategy-role" ${waiting?'disabled':''}>${ROLES.map(r=>`<option value="${r.id}" ${chosen.role===r.id?'selected':''}>${r.name}</option>`).join('')}</select><p class="role-explanation">${ROLES.find(r=>r.id===chosen.role).desc}</p><div class="strategy-zone-info"><b>${zoneOf(chosen.slot).symbol} ${zoneOf(chosen.slot).name}</b><p>${zoneOf(chosen.slot).desc}</p></div>`:''}<div class="strategy-bonds"><span class="eyebrow">İKİLİ BAĞLAR</span>${bonds.length?bonds.map(l=>{const [a,b]=l.members.map(id=>plan.find(p=>p.id===id));return `<p class="${adjacent(a.slot,b.slot)?'nearby':''}"><b>✦ ${l.name}</b><span>${adjacent(a.slot,b.slot)?'Komşular · 3 ortak saldırıda dolar':'Uzaklar · 4 ortak saldırıda dolar'}</span></p>`;}).join(''):'<p>Bu takımda özel ikili yok. Koruma ve grup uyumunu kullan.</p>'}</div></aside></div>
 <div class="strategy-footer"><p role="status">${connected?waiting?'Rakibin planı gizli. Hazırlık bitince mücadele başlar.':game.mode==='local'?(side===0?'Planını kilitle; ardından cihazı diğer oyuncuya ver.':'Planını kilitleyince iki diziliş açılır ve mücadele başlar.'):'Rakibin planını göremez. İkiniz de kilitleyince mücadele başlar.':'Bağlantı bekleniyor. Planını düzenleyebilirsin; onay için iki oyuncu da bağlı olmalı.'}</p>${waiting&&online&&!rematch?'<button class="outline" data-action="strategy-unlock">Planımı düzenle</button>':`<button class="outline" data-action="strategy-auto" ${waiting?'disabled':''}>Önerilen diziliş</button>`}<button class="primary" data-action="strategy-confirm" ${waiting||!connected?'disabled':''}>${waiting?'Rakip bekleniyor…':rematch?'Planı kilitle · Rövanş →':'Planı kilitle →'}</button></div></div>`;
}
export function handoffMarkup(name,esc){return `<div class="strategy-handoff"><span class="eyebrow">PLAN KAYDEDİLDİ · GİZLİ HAZIRLIK</span><div class="handoff-symbol">◇</div><h2>Cihazı ${esc(name)}<br>oyuncusuna ver.</h2><p>İlk oyuncunun dizilişi gizlendi.<br>Kendi planını hazırlamak için devam et.</p><button class="primary" data-action="strategy-handoff">Planımı hazırla →</button></div>`;}
